// Step 1: Build the JAR
// mvn clean package (produces target/order-service-1.0.0.jar)

// Step 2: Dockerfile in project root
FROM eclipse-temurin:17-jre-alpine
WORKDIR /app
COPY target/order-service-1.0.0.jar app.jar
EXPOSE 8080
ENTRYPOINT ["java", "-Xmx512m", "-jar", "app.jar"]

// Step 3: Build the image
// docker build -t order-service:1.0 .
// This creates an image tagged order-service:1.0

// Step 4: Run locally
// docker run -p 8080:8080 -e SPRING_PROFILES_ACTIVE=dev order-service:1.0
// Access at http://localhost:8080/orders

// Step 5: Tag for registry
// docker tag order-service:1.0 myregistry/order-service:1.0

// Step 6: Push to registry
// docker push myregistry/order-service:1.0
